</confidence>
Do not provide any other text or markdown fences.

Here is the original Java 8 code you have to translate:
<original_code>
import java.io.*;

public class Main {
    private static int nextInt(BufferedReader in) throws IOException {
        int c;
        do {
            c = in.read();
        } while (c != -1 && c <= ' ');
        if (c == -1) {
            throw new EOFException("Unexpected end of input");
        }
        boolean neg = (c == '-');
        if (neg) {
            c = in.read();
        }
        int number = 0;
        while (c >= '0' && c <= '9') {
            number = number * 10 + (c - '0');
            c = in.read();
        }
        return neg ? -number : number;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = nextInt(br);
        if (n > 20) {
            System.out.println(0);
            return;
        }
        int[][] p = new int[n][5];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < 5; j++) {
                p[i][j] = nextInt(br);
            }
        }

        java.util.List<Integer> good = new java.util.ArrayList<>();
        for (int i = 0; i < n; i++) {
            boolean ok = true;
            for (int j = 0; j < n && ok; j++) {
                if (i == j) continue;
                for (int k = j + 1; k < n; k++) {
                    if (i == k) continue;
                    if (getAn(p[i], p[j], p[k]) < 90) {
                        ok = false;
                        break;
                    }
                }
            }
            if (ok) good.add(i + 1);
        }

        StringBuilder sb = new StringBuilder();
        sb.append(good.size());
        for (int v : good) {
            sb.append('\n').append(v);
        }
        System.out.println(sb.toString());
    }

    static double getAn(int[] p1, int[] p2, int[] p3) {
        double dot = 0, aLen = 0, bLen = 0;
        for (int i = 0; i < p1.length; i++) {
            dot += (p2[i] - p1[i]) * (p3[i] - p1[i]);
            aLen += (p2[i] - p1[i]) * (p2[i] - p1[i]);
            bLen += (p3[i] - p1[i]) * (p3[i] - p1[i]);
        }
        return 180 * Math.acos(dot / Math.sqrt(aLen * bLen)) / Math.PI;
    }
}
